local PotteryWheelMaker = {}
local PRODUCTS = {
    iron_pottery_wheel = { name = "Železno lončarsko kolo", ironCost = 3, woodCost = 3, leatherCost = 1, time = 5, cost = 175, prestige = 4, happiness = 2, description = "Železno lončarsko kolo za oblikovanje keramike." },
    bronze_pottery_wheel = { name = "Bronasto lončarsko kolo", bronzeCost = 3, ironCost = 1, woodCost = 3, leatherCost = 1, time = 7, cost = 425, prestige = 6, happiness = 3, description = "Bronasto lončarsko kolo za fino keramiko." },
    silver_pottery_wheel = { name = "Srebrno lončarsko kolo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 11, cost = 1020, prestige = 11, happiness = 4, description = "Srebrno lončarsko kolo za plemiške lončarje." },
    gilded_pottery_wheel = { name = "Pozlačeno lončarsko kolo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 15, cost = 2200, prestige = 20, happiness = 5, description = "Pozlačeno lončarsko kolo za dvorne lončarje." },
    jewel_set_pottery_wheel = { name = "Draguljasto lončarsko kolo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 19, cost = 4750, prestige = 36, happiness = 7, description = "Draguljasto lončarsko kolo za kraljevske lončarje." },
    royal_sovereign_pottery_wheel = { name = "Kraljevski suvereno lončarsko kolo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 26, cost = 10200, prestige = 68, happiness = 13, description = "Suvereno lončarsko kolo z biseri za krono." },
}
local BUILDINGS = {
    potterywheel_workshop = { name = "Lončarska delavnica", cost = { gold = 355, wood = 190, stone = 135, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    potterywheel_house = { name = "Lončarska hiša", cost = { gold = 1255, wood = 375, stone = 280, silver = 7, iron = 7 }, upkeep = 26, qualityBonus = 18 },
    master_potterywheel_atelier = { name = "Mojstrski lončarski atelje", cost = { gold = 3140, wood = 435, stone = 535, silver = 37, gold = 7 }, upkeep = 74, qualityBonus = 30 },
    sovereign_potterywheel_palace = { name = "Suverena lončarska palača", cost = { gold = 13300, wood = 660, stone = 845, gold = 85, jewel = 19 }, upkeep = 260, qualityBonus = 55, prestigeBonus = 50 },
}
PotteryWheelMaker.ironStock = 14; PotteryWheelMaker.bronzeStock = 12; PotteryWheelMaker.woodStock = 18; PotteryWheelMaker.leatherStock = 8; PotteryWheelMaker.silverStock = 8; PotteryWheelMaker.goldStock = 6; PotteryWheelMaker.jewelStock = 4; PotteryWheelMaker.pearlStock = 4
PotteryWheelMaker.productStock = {}; PotteryWheelMaker.buildings = {}; PotteryWheelMaker.maker = nil; PotteryWheelMaker.activeMaking = {}; PotteryWheelMaker.totalProducts = 0; PotteryWheelMaker.dayTimer = 0
function PotteryWheelMaker.init() PotteryWheelMaker.ironStock=14; PotteryWheelMaker.bronzeStock=12; PotteryWheelMaker.woodStock=18; PotteryWheelMaker.leatherStock=8; PotteryWheelMaker.silverStock=8; PotteryWheelMaker.goldStock=6; PotteryWheelMaker.jewelStock=4; PotteryWheelMaker.pearlStock=4; PotteryWheelMaker.productStock={}; PotteryWheelMaker.buildings={}; PotteryWheelMaker.maker=nil; PotteryWheelMaker.activeMaking={}; PotteryWheelMaker.totalProducts=0; PotteryWheelMaker.dayTimer=0; print("[PotteryWheelMaker] Royal Pottery Wheel Maker System initialized (6 products, 4 buildings)") end
function PotteryWheelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PotteryWheelMaker.maker={name=n or ("Lončar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lončar najet: %s (spretnost: %d)",PotteryWheelMaker.maker.name,s),"success") end; return true end
function PotteryWheelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PotteryWheelMaker.build(id) local ok,e=PotteryWheelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PotteryWheelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PotteryWheelMaker.getQualityBonus() local b=0; for _,bd in ipairs(PotteryWheelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PotteryWheelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PotteryWheelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PotteryWheelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PotteryWheelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PotteryWheelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PotteryWheelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PotteryWheelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PotteryWheelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PotteryWheelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PotteryWheelMaker.buildings==0 then return false,"Potrebna lončarska delavnica" end; if not PotteryWheelMaker.maker then return false,"Potreben lončar" end; return true end
function PotteryWheelMaker.make(pt,qty) qty=qty or 1; local ok,e=PotteryWheelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PotteryWheelMaker.ironStock=PotteryWheelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PotteryWheelMaker.bronzeStock=PotteryWheelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PotteryWheelMaker.woodStock=PotteryWheelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PotteryWheelMaker.leatherStock=PotteryWheelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PotteryWheelMaker.silverStock=PotteryWheelMaker.silverStock-d.silverCost*qty end; if d.goldCost then PotteryWheelMaker.goldStock=PotteryWheelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PotteryWheelMaker.jewelStock=PotteryWheelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PotteryWheelMaker.pearlStock=PotteryWheelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PotteryWheelMaker.maker then t=math.max(1,t-math.floor(PotteryWheelMaker.maker.skill/13)) end; table.insert(PotteryWheelMaker.activeMaking,{id="potterywheel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PotteryWheelMaker.completeMaking(m) local q=1.0+(PotteryWheelMaker.getQualityBonus()/100); if PotteryWheelMaker.maker then q=q+(PotteryWheelMaker.maker.skill/140) end; q=math.min(2.5,q); PotteryWheelMaker.productStock[m.productType]=(PotteryWheelMaker.productStock[m.productType] or 0)+m.quantity; PotteryWheelMaker.totalProducts=PotteryWheelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PotteryWheelMaker.maker then PotteryWheelMaker.maker.itemsMade=PotteryWheelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PotteryWheelMaker.maker.skill=math.min(100,PotteryWheelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kolo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"potterywheel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PotteryWheelMaker.update(dt) if not _G.state then return end; PotteryWheelMaker.dayTimer=PotteryWheelMaker.dayTimer+dt; if PotteryWheelMaker.dayTimer>=30 then PotteryWheelMaker.dayTimer=0; for i=#PotteryWheelMaker.activeMaking,1,-1 do local m=PotteryWheelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PotteryWheelMaker.completeMaking(m); table.remove(PotteryWheelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PotteryWheelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PotteryWheelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PotteryWheelMaker.getStats() return {ironStock=PotteryWheelMaker.ironStock,bronzeStock=PotteryWheelMaker.bronzeStock,woodStock=PotteryWheelMaker.woodStock,leatherStock=PotteryWheelMaker.leatherStock,silverStock=PotteryWheelMaker.silverStock,goldStock=PotteryWheelMaker.goldStock,jewelStock=PotteryWheelMaker.jewelStock,pearlStock=PotteryWheelMaker.pearlStock,productStock=PotteryWheelMaker.productStock,numBuildings=#PotteryWheelMaker.buildings,hasMaker=PotteryWheelMaker.maker~=nil,makerName=PotteryWheelMaker.maker and PotteryWheelMaker.maker.name or "—",makerSkill=PotteryWheelMaker.maker and PotteryWheelMaker.maker.skill or 0,activeMaking=#PotteryWheelMaker.activeMaking,totalProducts=PotteryWheelMaker.totalProducts} end
return PotteryWheelMaker
